3. use crate::mm::phys::phys_view;
4. 
5. //==================================================================================================
6. // Global-token attachment (deferred to the proving phase)
7. //==================================================================================================
8. 
9. /// The manager brokers the *global* frame partition: its abstract view coincides with
10. /// `phys_view().frames`. This is the §8 ghost-token attachment; the proving phase realizes it
11. /// with a token over the `frame::INSTANCE` / `PhysMemoryManager` singletons.
12. pub proof fn lemma_manager_attached(m: &PhysMemoryManager)
13.     ensures
14.         m@ == phys_view().frames,
15. {
16.     admit();
17. }
18. 
19. //==================================================================================================
20. // Kernel-path transitions (frame::alloc / frame::alloc_contiguous take no `self`)
21. //==================================================================================================
22. 
23. /// Effect of a single kernel-frame allocation on the brokered partition: the freshly returned
24. /// `addr` was free and becomes reserved with refcount 1. `frame::alloc` carries no `self`, so the
25. /// link to `self@` is supplied here and discharged by the global-token attachment in the proving
26. /// phase.
27. pub proof fn lemma_kernel_alloc_one(pre: FrameAllocView, post: FrameAllocView, addr: int)
28.     requires
29.         pre.wf(),
30.     ensures
31.         pre.free_frames.contains(addr),
32.         post == pre.alloc_one(addr),
33.         post.wf(),
34. {
35.     admit();
36. }
37. 
38. /// Effect of a contiguous kernel-frame allocation: `frames` owns `count` physically contiguous
39. /// frames starting at some page-aligned `base`, all of which were free and become reserved.
40. pub proof fn lemma_kernel_alloc_contiguous(
41.     pre: FrameAllocView,
42.     post: FrameAllocView,
43.     frames: Seq<KernelFrame>,
44.     count: nat,
45. )
46.     requires
47.         pre.wf(),
48.     ensures
49.         frames.len() == count,
50.         crate::mm::phys::manager::kernel_frames_contiguous(frames, count),
51.         post == pre.book_all(crate::mm::phys::manager::kernel_addr_set(frames)),
52.         pre.all_free(crate::mm::phys::manager::kernel_addr_set(frames)),
53.         post.wf(),
54. {
55.     admit();
56. }
57. 
58. /// The base address returned by a contiguous allocation, advanced by any in-range frame index,
59. /// stays within the address space — `frame::alloc_contiguous` guarantees the whole `count`-frame
60. /// span fits a `usize`, so no intermediate offset overflows. Admitted here; the proving phase
61. /// derives it from the contiguous allocator's range bound.
62. pub proof fn lemma_contig_no_overflow(base_raw: usize, idx: usize, count: usize)
63.     requires
64.         idx < count,
65.         base_raw as int + (count as int) * spec_page_size() <= usize::MAX as int,
66.     ensures
67.         (idx as int) * spec_page_size() <= usize::MAX as int,
68.         base_raw as int + (idx as int) * spec_page_size() <= usize::MAX as int,
69. {
70.     let ps: int = spec_page_size();
71.     // `spec_page_size() == arch::mem::PAGE_SIZE as int`, a `usize` cast, hence non-negative.
72.     assert(ps >= 0);
73.     // Monotonicity of multiplication by a non-negative factor: idx < count ==> idx*ps <= count*ps.
74.     assert((idx as int) * ps <= (count as int) * ps) by (nonlinear_arith)
75.         requires
76.             idx as int <= count as int,
77.             ps >= 0,
78.     ;
79.     // base_raw >= 0 (a `usize`), so both bounds follow linearly from base_raw + count*ps <= MAX.
80. }
81. 
82. //==================================================================================================
83. // User bulk-path transitions
84. //==================================================================================================
85. 
86. /// Booking the empty set leaves a frame partition unchanged.
87. pub proof fn lemma_book_all_empty(base: FrameAllocView)
88.     ensures
89.         base.book_all(Set::<int>::empty()) == base,
90. {
91.     let booked = base.book_all(Set::<int>::empty());
92.     assert(booked.allocated_frames =~= base.allocated_frames);
93.     assert(booked.free_frames =~= base.free_frames);
94.     assert(booked.refcounts =~= base.refcounts);
95. }
96. 
97. /// Booking a set and then allocating one more address `a` equals booking the extended set
98. /// `s ∪ {a}`. The two `FrameAllocView` transitions coincide field-by-field, independent of
99. /// whether `a` was already in `s` (`alloc_one`/`insert` are idempotent on the booked fields).
100. pub proof fn lemma_book_all_alloc_one(base: FrameAllocView, s: Set<int>, a: int)
101.     ensures
102.         base.book_all(s).alloc_one(a) == base.book_all(s.insert(a)),
103. {
104.     let lhs = base.book_all(s).alloc_one(a);
105.     let rhs = base.book_all(s.insert(a));
106.     assert(lhs.allocated_frames =~= rhs.allocated_frames);
107.     assert(lhs.free_frames =~= rhs.free_frames);
108.     assert(lhs.refcounts =~= rhs.refcounts);
109. }
110. 
111. /// The address set of an empty handle sequence is empty.
112. pub proof fn lemma_user_addr_set_empty(frames: Seq<UserFrame>)
113.     requires
114.         frames.len() == 0,
115.     ensures
116.         crate::mm::phys::manager::user_addr_set(frames) == Set::<int>::empty(),
117. {
118.     assert(crate::mm::phys::manager::user_addr_set(frames) =~= Set::<int>::empty());
119. }
120. 
121. /// Pushing a handle onto a sequence inserts its address into the sequence's address set.
122. pub proof fn lemma_user_addr_set_push(frames: Seq<UserFrame>, uf: UserFrame)
123.     ensures
124.         crate::mm::phys::manager::user_addr_set(frames.push(uf))
125.             == crate::mm::phys::manager::user_addr_set(frames).insert(uf@),
126. {
127.     let lhs = crate::mm::phys::manager::user_addr_set(frames.push(uf));
128.     let rhs = crate::mm::phys::manager::user_addr_set(frames).insert(uf@);
129.     assert forall|a: int| lhs.contains(a) implies rhs.contains(a) by {
130.         let i = choose|i: int|
131.             0 <= i < frames.push(uf).len() && #[trigger] frames.push(uf)[i]@ == a;
132.         if i < frames.len() {
133.             assert(frames.push(uf)[i] == frames[i]);
134.         } else {
135.             assert(i == frames.len());
136.             assert(frames.push(uf)[i] == uf);
137.         }
138.     }
139.     assert forall|a: int| rhs.contains(a) implies lhs.contains(a) by {
140.         if a == uf@ {
141.             assert(frames.push(uf)[frames.len() as int] == uf);
142.         } else {
143.             let i = choose|i: int| 0 <= i < frames.len() && #[trigger] frames[i]@ == a;
144.             assert(frames.push(uf)[i] == frames[i]);
145.         }
146.     }
147.     assert(lhs =~= rhs);
148. }
149. 
