151. /// every frame already taken, restoring the partition to its pre-call state. `Drop` side effects
152. /// are not modeled in exec, so the restoration is asserted here.
153. pub proof fn lemma_user_bulk_err_restored(m: &PhysMemoryManager, pre: FrameAllocView)
154.     requires
155.         pre.wf(),
156.     ensures
157.         m@ == pre,
158. {
159.     admit();
160. }
161. 
