         idx < count,
         base_raw as int + (count as int) * spec_page_size() <= usize::MAX as int,
     ensures
         (idx as int) * spec_page_size() <= usize::MAX as int,
         base_raw as int + (idx as int) * spec_page_size() <= usize::MAX as int,
 {
     let ps: int = spec_page_size();
