     ensures
         match result {
             Ok(frame) => {
                 &&& frame.inv()
                 &&& crate::mm::phys::phys_view().frames.allocated_frames.contains(frame@)
             },
             Err(_) => crate::mm::phys::phys_view().frames.free_frames.is_empty(),
         },
 )]
 pub(super) fn alloc() -> Result<FrameAddress, Error> {
     instance().alloc()
 }

